/**
 * Grammarly-parity benchmark for the local rules engine: short email and chat snippets with what Grammarly flags in
 * them (rule id from the engine vocabulary, the exact span, the replacement or null when any fix of that span counts),
 * plus clean sentences in a natural email/chat register that must produce no suggestion at all.
 *
 * The rules engine runs with the content script's defaults: en-US, email context, neutral formality, not typing, and
 * the stripUrlsAndCode masks. See grammarly-parity.test.ts for the scoring.
 */

export interface ParityCase {
  text: string;
  rule: string;
  /** Exact text of the flagged span. */
  original: string;
  /** Expected replacement, or null when any replacement of that span counts. */
  replacement: string | null;
}

